    private boolean canReconcile(Map<String,Object> s){if(!List.of("RESERVED","DISPATCHED","SETTLED","RECONCILED").contains(str(s.get("status")))||"MANUAL_NOT_DISPATCHED".equals(s.get("outcome")))return false;if(yes(s.get("active"))&&time(s.get("staleAfter")).isAfter(now()))return false;return yes(s.get("active"))||s.get("actualInputTokens")==null&&s.get("confirmedInputTokens")==null||s.get("calculatedAmount")==null&&s.get("confirmedAmount")==null;}
